:root {
  --f-display: 'Bricolage Grotesque', 'Figtree', ui-sans-serif, system-ui, sans-serif;
  --f-ui: 'Figtree', ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  --f-mono: 'Spline Sans Mono', ui-monospace, 'SF Mono', Menlo, monospace;
  font-synthesis: none;
}

/*
 * The sign-in page, in Studio. codegen.mjs prepends the @font-face rules and styles/themes.css,
 * so every colour here is a token and the server's data-theme (Studio or legacy) picks the palette.
 * The markup is RemotePortalPage.loginPage: form.card > .brand, .err, .fld ×2, submit, .foot.
 */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  min-height: 100%;
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  /* minmax(0, …) so the card's 100% resolves against the viewport, not its own content. */
  grid-template-columns: minmax(0, 1fr);
  place-items: center;
  padding: 24px 16px;
  background:
    radial-gradient(ellipse 70% 50% at 50% -10%, var(--accent-soft), transparent 70%),
    var(--canvas);
  color: var(--ink);
  font: 400 14px/1.45 var(--f-ui);
  -webkit-font-smoothing: antialiased;
}

.card {
  width: min(400px, 100%);
  background: var(--sheet);
  border: 1px solid var(--card-edge);
  border-radius: 22px;
  box-shadow: var(--sh-float);
  padding: 32px 28px 24px;
}

.brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin-bottom: 24px;
  text-align: center;
}

/* The Studio logo tile: the server's SVG mark is replaced by the "g" with its degree ring. */
.mk {
  width: 64px;
  height: 64px;
  border-radius: 19px;
  background: linear-gradient(150deg, var(--accent), var(--accent-2));
  color: var(--accent-ink);
  box-shadow: var(--sh-card);
  display: grid;
  place-items: center;
  position: relative;
  margin-bottom: 4px;
}

.mk svg {
  display: none;
}

.mk::before {
  content: 'g';
  font: 800 38px/1 var(--f-display);
  margin-top: -6px;
}

.mk::after {
  content: '';
  position: absolute;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 3px solid var(--accent-ink);
  top: 10px;
  right: 10px;
}

h1 {
  font: 700 26px/1.1 var(--f-display);
  letter-spacing: -0.03em;
}

.sub {
  font-size: 13px;
  color: var(--ink-2);
}

.fld {
  margin-bottom: 14px;
}

label {
  display: block;
  font-size: 12px;
  font-weight: 650;
  color: var(--ink-2);
  margin: 0 0 6px;
}

input {
  width: 100%;
  height: 44px;
  background: var(--field);
  border: 1px solid var(--line-2);
  border-radius: 12px;
  padding: 0 14px;
  font: inherit;
  font-size: 16px;
  color: var(--ink);
  outline: none;
  transition:
    border-color 0.12s,
    box-shadow 0.12s;
}

input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

input:focus-visible {
  outline: none;
}

button {
  font: inherit;
  cursor: pointer;
}

button[type='submit'] {
  width: 100%;
  height: 46px;
  margin-top: 8px;
  border: 0;
  border-radius: 12px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 15px;
  font-weight: 650;
  box-shadow: var(--sh-1);
  transition: background-color 0.12s;
}

button[type='submit']:hover {
  background: var(--accent-2);
}

button[type='submit']:disabled {
  opacity: 0.65;
  cursor: progress;
}

button[type='submit']:disabled:hover {
  background: var(--accent);
}

.err {
  background: var(--bad-soft);
  color: var(--bad);
  font-size: 13px;
  font-weight: 600;
  border-radius: 12px;
  padding: 10px 12px;
  margin-bottom: 16px;
  text-align: center;
}

.err:empty {
  display: none;
}

.pw {
  position: relative;
}

.pw input {
  padding-right: 50px;
}

.pw input::-ms-reveal {
  display: none;
}

button.eye {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: transparent;
  color: var(--ink-3);
}

button.eye:hover {
  background: var(--seg-bg);
  color: var(--ink);
}

.eye svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.eye .i-hide,
.eye[aria-pressed='true'] .i-show {
  display: none;
}

.eye[aria-pressed='true'] .i-hide {
  display: block;
}

.caps {
  margin-top: 6px;
  font-size: 12px;
  font-weight: 600;
  color: var(--warn);
}

.foot {
  margin-top: 22px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  text-align: center;
  font-size: 12px;
  color: var(--ink-3);
  line-height: 1.6;
}

.warn {
  color: var(--warn);
}

.secure {
  color: var(--good);
}

[hidden] {
  display: none !important;
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition: none !important;
  }
}

"""#

    public static let serviceWorker = #"""
// Goel° portal service worker. It caches nothing: every page and API call goes to the server,
// which holds the session. It exists so an installed portal opens to a clear "server
// unreachable" screen instead of the browser's own error page when the daemon is down.

// The portal's own canvas and ink (styles/themes.css, light and dark), so the offline page looks
// like the app rather than a browser error. Two languages are enough for a screen that shows
// for seconds; the app itself carries the full catalogue.
const COPY = {
  en: {
    bar: 'Reconnecting to Goel°…',
    title: 'Can’t reach the Goel° server',
    body: 'Check that the daemon is running and this device is on the same network. This page retries every 10 seconds.',
    retry: 'Try again now',
    tab: 'Goel° — Reconnecting',
  },
  de: {
    bar: 'Verbindung zu Goel° wird wiederhergestellt …',
    title: 'Goel°-Server nicht erreichbar',
    body: 'Prüfe, ob der Daemon läuft und dieses Gerät im selben Netzwerk ist. Diese Seite versucht es alle 10 Sekunden erneut.',
    retry: 'Jetzt erneut versuchen',
    tab: 'Goel° — Verbindung wird hergestellt',
  },
}

function offlineHtml(language) {
  const lang = String(language || 'en').toLowerCase().startsWith('de') ? 'de' : 'en'
  const c = COPY[lang]
  return `<!doctype html><html lang="${lang}"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="refresh" content="10">
<title>${c.tab}</title>
<style>
  :root { color-scheme: light dark; --canvas: #f1f7f2; --ink: #18251f; --ink-2: #4c5953; --accent: #007d5f;
          --warn: #8a4b00; --warn-bg: rgba(200, 120, 0, .14); }
  @media (prefers-color-scheme: dark) {
    :root { --canvas: #121e18; --ink: #e9f1ec; --ink-2: #b2beb7; --accent: #52caa5;
            --warn: #f0b86a; --warn-bg: rgba(240, 184, 106, .16); }
  }
  body { margin: 0; font: 15px/1.5 -apple-system, system-ui, sans-serif; background: var(--canvas);
         color: var(--ink); display: grid; min-height: 100vh; place-items: center; }
  .bar { position: fixed; top: 0; left: 0; right: 0; padding: 8px 16px; background: var(--warn-bg);
         color: var(--warn); font-weight: 600; text-align: center; }
  main { max-width: 360px; padding: 24px; text-align: center; }
  h1 { font-size: 20px; margin: 0 0 8px; }
  p { margin: 0 0 16px; color: var(--ink-2); }
  a { color: var(--accent); font-weight: 600; }
</style></head><body>
<div class="bar" role="status">${c.bar}</div>
<main><h1>${c.title}</h1>
<p>${c.body}</p>
<a href="/">${c.retry}</a></main>
</body></html>`
}

self.addEventListener('install', () => self.skipWaiting())
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()))

self.addEventListener('fetch', (event) => {
  // Only whole-page loads: the event stream, streams and API calls must reach the server untouched.
  if (event.request.mode !== 'navigate') return
  event.respondWith(
    fetch(event.request).catch(
      () =>
        new Response(offlineHtml(self.navigator.language), {
          status: 503,
          headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' },
        }),
    ),
  )
})

